use std::{env,fs,time::Instant};
fn rss()->u64 {fs::read_to_string("/proc/self/status").unwrap().lines().find(|s|s.starts_with("VmRSS:")).unwrap().split_whitespace().nth(1).unwrap().parse().unwrap()}
fn main(){let a:Vec<_>=env::args().collect(); let bytes=fs::read(&a[2]).unwrap(); let before=rss();let mut parser=tree_sitter::Parser::new();let language=match a[1].as_str(){"c"=>tree_sitter_c::LANGUAGE,"cpp"=>tree_sitter_cpp::LANGUAGE,"python"=>tree_sitter_python::LANGUAGE,_=>tree_sitter_rust::LANGUAGE};parser.set_language(&language.into()).unwrap();let start=Instant::now();let tree=parser.parse(&bytes,None).unwrap();let parsed=rss();drop(parser);println!("{} {} {} {} {} {}",bytes.len(),tree.root_node().descendant_count(),before,parsed,rss(),start.elapsed().as_secs_f64());}
